/// Whether *any* Zellij pane currently backs process `id`, in any state -
/// running, suppressed, or exited-but-resurrectable. Unlike
/// [`Self::process_pane`], which ignores exited panes, this is the "is this
/// instance still represented in the cockpit at all" test.
///
/// The Agents pane uses it to drop agent process records orphaned by a
/// Zellij session restart: the record persists in the daemon (spawned
/// agents are durable, disposed by their caller), but its pane is gone
/// entirely, so it can never be focused or resurrected from here - it is
/// dead weight that otherwise piles up as one unreachable row per agent
/// ever spawned. An exited-but-present pane still passes (it is
/// resurrectable via `u`), so this only hides the truly paneless rows.
fn has_process_pane(&self, id: u64) -> bool {
    self.panes.iter().any(|p| p.role == PaneRole::Process(id))
}

