#[test]
fn agents_pane_hides_process_records_with_no_pane() {
    use std::collections::HashMap;
    // Three agent process records, but only #5 has a live pane and #6 an
    // exited-but-present one; #158 is orphaned (its pane vanished with a
    // past session). The orphan must not render - it is unreachable from
    // here - while the live and resurrectable ones both stay listed.
    let proc = |kind: &str, id: u64, label: &str| ProcessRow {
        kind: kind.to_string(),
        id,
        label: label.to_string(),
    };
    let pane = |id: u32, cmd: &str, exited: bool| PaneInfo {
        id,
        is_selectable: true,
        terminal_command: Some(cmd.to_string()),
        exited,
        ..Default::default()
    };
    let mut sidebar = pane_with(Mode::Agents);
    sidebar.processes = vec![
        proc("agent", 5, "live"),
        proc("agent", 6, "resurrectable"),
        proc("agent", 158, "orphan"),
    ];
    let mut panes = HashMap::new();
    panes.insert(
        0usize,
        vec![
            pane(40, "/bin/panopt _process-run --port 7600 5", false),
            pane(41, "/bin/panopt _process-run --port 7600 6", true),
        ],
    );
    sidebar.ingest_panes(PaneManifest { panes });
    sidebar.rebuild_items();

    let shown: Vec<u64> = sidebar
        .items
        .iter()
        .filter_map(|i| match i.target {
            ItemTarget::Process(id) => Some(id),
            _ => None,
        })
        .collect();
    assert_eq!(shown, vec![5, 6], "orphan #158 must be hidden, #5/#6 kept");
    // The live pane is marked live; the exited-but-present one is not, so
    // it still shows (resurrectable via `u`) but without the `*` marker.
    let live_of = |id: u64| {
        sidebar
            .items
            .iter()
            .find(|i| matches!(i.target, ItemTarget::Process(p) if p == id))
            .map(|i| i.live)
    };
    assert_eq!(live_of(5), Some(true));
    assert_eq!(live_of(6), Some(false));
}

